```typescript
// Checkout.test.tsx
import { render, screen, waitFor } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { vi, describe, it, expect, beforeEach } from 'vitest';
import { Checkout } from './Checkout';

// Mock the context hooks - gotta fake the boring infrastructure
const mockClearCart = vi.fn();
const mockProcessPayment = vi.fn();
const mockItems = [
  { id: '1', name: 'Kourier Board', price: 299.99 },
  { id: '2', name: 'Mag-poon', price: 149.99 }
];

vi.mock('./CartContext', () => ({
  useCart: () => ({ items: mockItems, total: 449.98, clearCart: mockClearCart })
}));

vi.mock('./PaymentContext', () => ({
  usePayment: () => ({ processPayment: mockProcessPayment })
}));

describe('Checkout - Happy Path (The Fun Way)', () => {
  beforeEach(() => {
    vi.clearAllMocks();
    mockProcessPayment.mockResolvedValue({ orderId: 'ORD-420-NICE' });
  });

  it('completes full checkout flow without wiping out', async () => {
    const user = userEvent.setup();
    const onComplete = vi.fn();
    render(<Checkout onComplete={onComplete} />);

    // Arrange & Act: Shipping step
    await user.type(screen.getByLabelText(/street address/i), '123 Metaverse Ave');
    await user.type(screen.getByLabelText(/city/i), 'Los Angeles');
    await user.selectOptions(screen.getByLabelText(/state/i), 'CA');
    await user.type(screen.getByLabelText(/zip code/i), '90210');
    await user.click(screen.getByRole('button', { name: /continue to payment/i }));

    // Assert: Now on payment
    expect(screen.getByRole('form', { name: /payment information/i })).toBeInTheDocument();

    // Act: Payment step
    await user.type(screen.getByLabelText(/card number/i), '4111111111111111');
    await user.type(screen.getByLabelText(/expiry/i), '12/25');
    await user.type(screen.getByLabelText(/cvv/i), '123');
    await user.type(screen.getByLabelText(/name on card/i), 'Y.T. Kourier');
    await user.click(screen.getByRole('button', { name: /review order/i }));

    // Assert: Review screen shows our stuff
    expect(screen.getByText(/kourier board/i)).toBeInTheDocument();
    expect(screen.getByText(/\$449\.98/)).toBeInTheDocument();

    // Act: Place order
    await user.click(screen.getByRole('button', { name: /place order/i }));

    // Assert: Confirmation
    await waitFor(() => {
      expect(screen.getByRole('status', { name: /order confirmation/i })).toBeInTheDocument();
    });
    expect(screen.getByText('ORD-420-NICE')).toBeInTheDocument();
    expect(onComplete).toHaveBeenCalledWith('ORD-420-NICE');
  });
});

describe('Validation - Crash Testing', () => {
  it('shows errors when shipping fields are empty', async () => {
    const user = userEvent.setup();
    render(<Checkout />);

    await user.click(screen.getByRole('button', { name: /continue to payment/i }));

    expect(screen.getByRole('alert', { name: /street address is required/i })).toBeInTheDocument();
    expect(screen.getByLabelText(/street address/i)).toHaveAttribute('aria-invalid', 'true');
  });

  it('rejects bogus ZIP codes', async () => {
    const user = userEvent.setup();
    render(<Checkout />);

    await user.type(screen.getByLabelText(/zip code/i), 'YOLO');
    await user.click(screen.getByRole('button', { name: /continue to payment/i }));

    expect(screen.getByText(/valid zip code required/i)).toBeInTheDocument();
  });
});

describe('Edge Cases - What Could Possibly Go Wrong?', () => {
  it('handles empty cart like a pro', () => {
    vi.mocked(useCart).mockReturnValue({ items: [], total: 0, clearCart: mockClearCart });
    render(<Checkout />);

    expect(screen.getByRole('alert')).toHaveTextContent(/cart is empty/i);
  });

  it('shows loading state and disables buttons during payment', async () => {
    mockProcessPayment.mockImplementation(() => new Promise(() => {})); // Never resolves
    const user = userEvent.setup();
    // ... navigate to review step ...

    await user.click(screen.getByRole('button', { name: /place order/i }));

    expect(screen.getByRole('button', { name: /processing/i })).toHaveAttribute('aria-busy', 'true');
    expect(screen.getByRole('button', { name: /back/i })).toBeDisabled();
  });
});
```

